hooks.command:
if [ -f "${PLUGIN_ROOT}/scripts/loom_checker.py" ]; then exec python3 "${PLUGIN_ROOT}/scripts/loom_checker.py" push --hook; else exec python3 -c 'import json, os, shlex, sys
checker = os.path.join(os.environ.get("PLUGIN_ROOT", ""), "scripts", "loom_checker.py")
def deny():
 print(f"BLOCK push.attestation: installed checker is unavailable at {checker}; restart Codex to load the installed plugin version", file=sys.stderr)
 raise SystemExit(2)
try:
 payload = json.load(sys.stdin)
 command = payload["tool_input"]["command"]
 if not isinstance(payload, dict) or payload.get("tool_name") != "Bash" or not isinstance(command, str) or not command.strip(): deny()
 tokens = shlex.split(command)
except Exception:
 deny()
if not tokens or any(ch in command for ch in "\n;&|<>$`()"): deny()
name = os.path.basename(tokens[0])
unsafe = {"-exec", "-execdir", "-ok", "-okdir", "-delete", "-fprint", "-fprint0", "-fprintf", "--pre", "--pre-glob"}
if any(token in unsafe or token.startswith("--output") for token in tokens[1:]): deny()
allowed = False
if name == "git":
 index = 1
 if len(tokens) > 2 and tokens[1] == "-C": index = 3
 if len(tokens) <= index: deny()
 sub = tokens[index]
 allowed = sub in {"status", "log", "diff", "show"}
 if sub == "branch": allowed = len(tokens) == index + 1 or (len(tokens) > index + 1 and tokens[index + 1] == "--list")
elif name in {"ls", "cat", "rg", "find"}:
 allowed = True
if not allowed: deny()' ; fi
